import { db } from "../lib/db";
import { SANDBOX } from "../lib/sandbox";
import type { SftpServer } from "../lib/sftp";
import { withServerSsh, exec, SETUP_TIMEOUT_MS } from "../lib/ssh-exec";
import {
  controlSpec,
  isGameFamily,
  isPowerAction,
  remoteLocateDir,
  runRcon,
  parsePlayers,
  computeNextRun,
  computeNextIntervalRun,
  shq,
  isSafeRemotePath,
  GAME_BACKUP_DIR,
  type GameControlSpec,
} from "../lib/game-control";
import type { Job } from "@prisma/client";

/**
 * Game server control-panel worker handlers.
 *
 * Registered in worker/index.ts:
 *   GAME_POWER:  gamePower,
 *   GAME_BACKUP: gameBackup,
 * and `gameScheduleSweep()` called on a ~60s timer.
 *
 * Everything runs over the platform's existing SSH (lib/ssh-exec withServerSsh —
 * host/port/root-password derived exactly like lib/sftp). Family/unit/path values
 * that reach the shell are compile-time constants or allowlisted (lib/game-control),
 * and the root password is never surfaced in an error (only a trimmed remote stderr
 * is, which never contains it).
 *
 * SANDBOX / no VM: handlers notify a simulation and touch nothing.
 */

const CONTROL_FIELDS = {
  id: true,
  userId: true,
  hostname: true,
  status: true,
  rootPassword: true,
  rootPasswordEnc: true,
  sshPort: true,
  dedicatedIp: { select: { address: true } },
  node: { select: { publicIp: true } },
  osTemplate: { select: { family: true } },
  gamePlan: { select: { gameFamily: true } },
} as const;

type ControlServer = {
  id: string;
  userId: string;
  hostname: string;
  status: string;
  rootPassword: string | null;
  rootPasswordEnc: string | null;
  sshPort: number | null;
  dedicatedIp: { address: string } | null;
  node: { publicIp: string } | null;
  osTemplate: { family: string | null };
  gamePlan: { gameFamily: string | null } | null;
};

async function notify(userId: string, title: string, body?: string, href?: string) {
  try {
    await db.notification.create({ data: { userId, title, body, href } });
  } catch (e) {
    console.error("[game-control] notify failed", e);
  }
}

function resolveSpec(server: ControlServer): GameControlSpec {
  const fam = server.gamePlan?.gameFamily ?? server.osTemplate?.family ?? null;
  if (!isGameFamily(fam)) throw new Error("not a game server");
  const spec = controlSpec(fam);
  if (!spec) throw new Error("no control spec for family");
  return spec;
}

/**
 * Build the remote unit-resolution + systemctl script. `hints`/`family` come from
 * the family's control spec (compile-time constants); `action` is one of the three
 * allowlisted verbs. Emits NXGP markers so a clean SSH exit is never mistaken for
 * a successful action (the same discipline as worker/game-update.ts).
 */
function powerScript(spec: GameControlSpec, action: string): string {
  const hints = spec.serviceHints.map(shq).join(" ");
  return [
    `unit=""`,
    `for c in ${hints}; do systemctl cat "$c" >/dev/null 2>&1 && { unit="$c"; break; }; done`,
    `if [ -z "$unit" ]; then unit=$(systemctl list-units --type=service --plain --no-legend 2>/dev/null | grep -i ${shq(spec.family)} | head -1 | awk '{print $1}'); fi`,
    `if [ -z "$unit" ]; then echo "NXGP:UNIT:NONE"; exit 0; fi`,
    `echo "NXGP:UNIT:$unit"`,
    `systemctl ${action} "$unit" >/dev/null 2>&1; echo "NXGP:RC:$?"`,
    `st=$(systemctl is-active "$unit" 2>/dev/null); echo "NXGP:STATE:${"$"}{st:-unknown}"`,
    `echo "NXGP:END"`,
  ].join("\n");
}

/** GAME_POWER — start/stop/restart the game SERVICE (not the VM). */
export async function gamePower(job: Job): Promise<void> {
  if (!job.serverId) throw new Error("game power: missing serverId");
  const server = (await db.server.findUnique({ where: { id: job.serverId }, select: CONTROL_FIELDS })) as ControlServer | null;
  if (!server) throw new Error(`Server ${job.serverId} not found`);
  const spec = resolveSpec(server);

  const p = (job.payload ?? {}) as { action?: string; announce?: boolean };
  const action = String(p.action ?? "");
  if (!isPowerAction(action)) throw new Error(`unsupported power action: ${action}`);
  const href = `/dashboard/servers/${server.id}?tab=manage`;

  if (SANDBOX) {
    await notify(
      server.userId,
      `Game service ${action} (sandbox) on ${server.hostname}`,
      `Sandbox only — no VM was contacted; the ${spec.label} service was not ${action}ed.`,
      href
    );

/**
 * Shared, injection-safe SSH execution foundation for the customer control
 * panel (websites, databases, one-click apps, cron & services).
 *
 * This is a plain server-side module (NO "use server", no client imports) so it
 * can be used by both the inline read helpers (lib/cpanel-inline.ts) and the
 * worker executors (worker/websites|databases|apps|services.ts). It NEVER runs
 * in the browser — the customer's root credentials stay on the server.
 *
 * It mirrors the hardening in worker/migrate-real.ts on two axes:
 *
 *   1. STRICT ALLOWLIST VALIDATION. Every non-secret value that will be
 *      interpolated into a remote command MUST match a shell-inert allowlist
 *      (regexes below contain no quotes/spaces/metacharacters/newlines) or the
 *      operation FAILS. We reject — never sanitize. Callers validate up front
 *      with the `assert*` helpers so a bad value can never reach a shell.
 *
 *   2. SECRETS NEVER TOUCH A COMMAND STRING. Generated DB / app passwords are
 *      written to the far side via a command's STDIN (`execInput`) or an SFTP
 *      file — never as an argv token. Command strings reference only file paths
 *      or values that passed the allowlist.
 *
 * Connection target + root password derivation is identical to lib/sftp.ts and
 * worker/ssl.ts (dedicated IP → own IP:22, else PUBLIC_IP:sshPort; user root).
 */
import { Client, type ClientChannel } from "ssh2";
import { randomBytes } from "node:crypto";
import { connectionTarget, serverRootPassword, type SftpServer } from "./sftp";

// ---- Timeouts -------------------------------------------------------------
export const SSH_CONNECT_TIMEOUT_MS = 15_000;
/** Quick inline reads (list/status/snapshot) — kept short so a slow box can't
 *  wedge a page render. */
export const QUICK_TIMEOUT_MS = 12_000;
/** Small mutating commands (write a vhost, create a DB, edit crontab). */
export const SETUP_TIMEOUT_MS = 60_000;
/** Long installs (php-fpm, an engine, an app download). */
export const INSTALL_TIMEOUT_MS = Number(process.env.CPANEL_INSTALL_TIMEOUT_MS ?? 15 * 60_000);

// ---- Strict allowlist validators (throw on any violation) -----------------
// Every charset below is deliberately shell-inert.
export const DOMAIN_RE =
  /^(?=.{1,253}$)([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,24}$/;
/** DB / DB-user identifier: letters, digits, underscore. */
export const IDENT_RE = /^[A-Za-z0-9_]{1,32}$/;
/** PHP version like 8.3 / 7.4. */
export const PHP_VERSION_RE = /^\d\.\d$/;
/** systemd unit name (bare service name we control from a fixed list). */
export const SERVICE_RE = /^[a-z0-9][a-z0-9_.-]{0,63}$/;
/** Absolute path with a safe charset, no traversal / double slash. */
export const PATH_RE = /^\/[A-Za-z0-9._/-]{1,255}$/;
/** A single crontab time field: digits, * , - , / and commas only. */
export const CRON_FIELD_RE = /^[0-9*,/-]{1,64}$/;
/** App slug from our fixed catalog. */
export const SLUG_RE = /^[a-z][a-z0-9-]{0,31}$/;

export function assert(cond: unknown, msg: string): asserts cond {
  if (!cond) throw new Error(msg);
}

export function assertDomain(d: string): void {
  assert(typeof d === "string" && DOMAIN_RE.test(d), `Unsupported domain: ${d}`);
}
export function assertIdent(v: string, what: string): void {
  assert(typeof v === "string" && IDENT_RE.test(v), `Unsupported ${what}: ${v}`);
}
export function assertPhp(v: string): void {
  assert(typeof v === "string" && PHP_VERSION_RE.test(v), `Unsupported PHP version: ${v}`);
}
export function assertService(v: string): void {
  assert(typeof v === "string" && SERVICE_RE.test(v), `Unsupported service: ${v}`);
}
export function assertPath(p: string): void {
  assert(
    typeof p === "string" && PATH_RE.test(p) && !p.includes("..") && !p.includes("//"),
    `Unsupported path: ${p}`
  );
}
export function assertSlug(s: string): void {
  assert(typeof s === "string" && SLUG_RE.test(s), `Unsupported app: ${s}`);

